# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_agent() {
    opencode debug agents 2>/dev/null | jq -b -r '.[] | select(.hidden != true) | "\(.id)\t\(.description)"'
}

_choice_auth_credential() {
    local target=${argc_target:-}
    opencode auth list --format json 2>/dev/null |
        jq -b -r --arg target "$target" '.[] | select($target == "" or .id == $target) | .connections[] | "\(.id)\t\(.label)"'
}

_choice_auth_target() {
    opencode auth list --format json 2>/dev/null | jq -b -r '.[] | "\(.id)\t\(.name)"'
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_mcp_add_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 3 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_model() {
    opencode models 2>/dev/null
}

_choice_plugin() {
    opencode plugin list 2>/dev/null | _argc_util_transform_table 'ID'
}

_choice_session() {
    opencode session list --format json --max-count 50 2>/dev/null |
        jq -b -r '.[] | select(.id != null) | "\(.id)\t\(.title)"'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
